/**  Each side of a difference compared with the other side. */
export type DifferenceWords = {
	/**
	 *  Left compared with right: left text the right lacks; removals are right text the left
	 *  lacks, placed where it would sit in the left.
	 */
	left: SideWordChanges<LeftLine>,
	/**  Right compared with left. */
	right: SideWordChanges<RightLine>,
};

/**  A comment of a thread. */
export type DiscussionComment = {
	/**  Who wrote it; `None` for a deleted user. */
	author: Person | null,
	/**  When it was written: GitLab's ISO 8601 time, as sent. */
	createdAt: string,
	/**
	 *  Edited as GitLab's `Note#edited?` means it: `lastEditedBy` a person and `lastEditedAt` after `createdAt`
	 *  (`app/models/note.rb:533-545`; resolving moves `lastEditedAt` alone, measured, design §1.3).
	 */
	edited: NoteEdit | null,
	/**  GitLab's `bodyHtml` reduced by `described_on` on the merge request's page (RK60, RK66: no other path). */
	body: Description,
	/**  Its page on GitLab; `None` when GitLab's `url` is not the one it builds for this note. */
	page: WebPage | null,
};

/**
 *  When the merge-request page reads each row's open discussions: as the list arrives, on the first hover of a
 *  row's count, or never.
 */
export type DiscussionDetails = "full" | "lazy" | "off";

/**
 *  A discussion's id: GitLab's 40 lowercase hex digits, the REST routes' `:discussion_id` (from GraphQL
 *  `gid://gitlab/Discussion/<hex>`). The window sends it back; nothing else deserializes.
 */
export type DiscussionId = string;

/**  A note as the window shows it. */
export type DiscussionNote = {
	/**  Who wrote it; `None` for a deleted user. */
	author: Person | null,
	/**  When it was written: GitLab's ISO 8601 time, as sent. */
	createdAt: string,
	/**  Its raw body. */
	text: string,
	/**  Its page on GitLab; `None` when GitLab's `url` is not the one it builds for this note. */
	page: WebPage | null,
	/**  The users it mentions. */
	mentions: Mention[],
};

/**  Where a discussion is. */
export type DiscussionPlace = 
/**  On the merge request itself: the first person's note has no `position`. */
{ kind: "overview" } | 
/**  On the diff: `filePath`, and `newLine`, else `oldLine` (both may be null). */
{ kind: "file"; 
/**  The file's path. */
path: string; 
/**  The line, on the new side when it has one. */
line: number | null };

/**  A discussion's whole thread, and what the viewer may do in it. */
export type DiscussionThread = {
	/**  The same turn data the box gets, built by the same function (resolved or not). */
	discussion: OpenDiscussion,
	/**  Whether it is resolved. */
	resolved: boolean,
	/**  Every person note, oldest first; never empty (the discussion has one). System notes left out (RK61). */
	comments: DiscussionComment[],
	/**  The viewer's pending drafts in this discussion, in GitLab's order. */
	drafts: PendingDraft[],
	/**  All the viewer's pending drafts on this merge request (C9). */
	pending: number,
	/**  Whether the viewer may comment. */
	commenting: Commenting,
	/**  `Discussion.userPermissions.resolveNote`, and the discussion resolvable. */
	mayResolve: boolean,
};

/**  How reading a discussion's whole thread ended. */
export type DiscussionThreadReply = 
/**  The thread. */
{ kind: "read"; 
/**  The thread. */
thread: DiscussionThread } | 
/**  The merge request answered, without this discussion (deleted, or never there). */
{ kind: "notFound" } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  glab's or GitLab's words, `page.rs` `NO_PROJECT`, or the 200-note rule's sentence. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  How a write to a discussion ended. */
export type DiscussionWriteReply = 
/**  GitLab took it. */
{ kind: "sent" } | 
/**
 *  GitLab answered 4xx: `HttpAnswer::reason()` (its `message`/`error`, glab's line, `HTTP <code>`); also a
 *  blank text, before any glab run: "There is nothing to send."
 */
{ kind: "refused"; 
/**  Why. */
reason: string } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  No HTTP answer (glab failed, timed out), a 5xx or another status (its reason), or `NO_PROJECT`. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  How asking for a merge request's open discussions ended. */
export type DiscussionsAnswer = 
/**  Its resolvable, unresolved discussions, in GitLab's order. */
{ kind: "open"; 
/**  The discussions. */
discussions: OpenDiscussion[] } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  glab failed, timed out or answered something unexpected, in glab's or yamt's words. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

export type DiskChange = {
	path: string,
	result: DiskResult,
};

/**  What yamt did with a file that changed on disk. */
export type DiskResult = { kind: "Staged" } | 
/**  Not staged: the file still has this many open blocks and raw regions, at least one. */
{ kind: "MarkersLeft"; conflicts: number } | 
/**  Not staged, by design: a `working-tree-encoding` file or a submodule that is not checked out. */
{ kind: "LeftAsIs" } | { kind: "StageFailed"; message: string };

/**  Counts the settles of one file's disk changes, from the session's first version; a view is built from one version. */
export type DiskVersion = number;

export type Eol = "Lf" | "CrLf" | "Mixed";

/**  A failed job of a merge request's latest pipeline, the latest run of it. */
export type FailedJob = {
	/**  The job's name. */
	name: string,
	/**  Its stage's name. */
	stage: string,
	/**  Whether the pipeline may pass while it fails. */
	allowFailure: boolean,
	/**  Its log page; `None` when GitLab is not on https or sent an odd path. */
	page: WebPage | null,
};

export type FileEntry = {
	path: string,
	status: FileStatus,
	unsupported: UnsupportedReason | null,
};

export type FileMergeData = {
	path: string,
	middle: Middle,
	local: string,
	remote: string,
	deleted: Side | null,
	eol: Eol,
	chunks: MergeChunk[],
	disk_version: DiskVersion,
};

export type FileSides = {
	path: string,
	reason: UnsupportedReason | null,
	local: SideContent,
	remote: SideContent,
	disk_version: DiskVersion,
};

export type FileStatus = "Unresolved" | 
/**  Unmerged for git, with the resolution git rerere replayed on disk, not yet reviewed (plan §2 #90). */
"Remembered" | "Resolved";

/**  Whether GitLab's diff is exactly the window's. */
export type GitLabCheck = 
/**  It is: posting goes to this merge request. */
{ kind: "linedUp"; 
/**  The merge request. */
merge_request: MergeRequestRef } | 
/**  It is not. */
{ kind: "notLinedUp"; 
/**  Why. */
why: NotLinedUp };

/**  Whether the window shows the button: decided once at start, offline. */
export type GitLabProject = 
/**  No repository, or no remote on a GitLab server. */
{ kind: "none" } | 
/**  A repository with a remote on a GitLab server. */
{ kind: "found"; 
/**  The absolute common git dir (lossy UTF-8): the key filters are remembered by. */
repository: string };

/**
 *  A Gravatar picture's address: `https://secure.gravatar.com` or `https://www.gravatar.com`, the path
 *  `/avatar/<32 or 64 hex digits>`, an optional query of `[A-Za-z0-9=&%._-]`; only `avatar_source` makes one.
 */
export type GravatarAddress = string;

/**  A heading's level, `<h1>` to `<h6>`. */
export type HeadingLevel = 
/**  `<h1>`. */
"h1" | 
/**  `<h2>`. */
"h2" | 
/**  `<h3>`. */
"h3" | 
/**  `<h4>`. */
"h4" | 
/**  `<h5>`. */
"h5" | 
/**  `<h6>`. */
"h6";

/**  What a running server sends the window; `Exited` comes once, last. */
export type HostEvent = { kind: "Message"; text: string } | { kind: "Log"; line: string } | { kind: "Exited"; code: number | null };

/**  One length: a bare number is pixels, as on GitLab. */
export type ImageLength = 
/**  `12` or `12px`. */
{ kind: "pixels"; 
/**  0 to 9999. */
value: number } | 
/**  `40%`. */
{ kind: "percent"; 
/**  0 to 9999, as written. */
value: number };

/**
 *  GitLab's `width`/`height` on an image, each only in GitLab's form `\A\d{1,4}(%|px)?\z` (Banzai
 *  `AttributesFilter::VALID_SIZE_REGEX`); a value outside it is as if not written (request A3).
 */
export type ImageSize = 
/**  A width alone. */
{ kind: "width"; 
/**  The width. */
width: ImageLength } | 
/**  A height alone. */
{ kind: "height"; 
/**  The height. */
height: ImageLength } | 
/**  A width and a height. */
{ kind: "both"; 
/**  The width. */
width: ImageLength; 
/**  The height. */
height: ImageLength };

/**
 *  A zero-width place inside one line of one text: `column` UTF-16 code units from the line's
 *  start, at most the line's length without its line break.
 */
export type InlinePoint<L> = {
	/**  The line holding the point. */
	line: L,
	/**  Column of the point. */
	column: number,
};

/**
 *  Changed text inside one line of one text: `len` UTF-16 code units from column `start`
 *  (the unit of JavaScript strings and `CodeMirror` positions). Never contains a line break.
 */
export type InlineRange<L> = {
	/**  The line holding the range. */
	line: L,
	/**  Column of the first changed code unit. */
	start: number,
	/**  Number of changed code units; never zero. */
	len: number,
};

export type IpcError = { kind: "Git"; message: string } | { kind: "UnknownPath"; path: string } | { kind: "Unsupported"; path: string; reason: UnsupportedReason } | { kind: "WriteFailed"; path: string; message: string } | { kind: "NotAFile"; path: string } | { kind: "ReadFailed"; path: string; message: string } | { kind: "SettingsBroken"; path: string; message: string } | { kind: "NotAbsolute"; path: string } | { kind: "NoConfigFolder" } | { kind: "MergeAborted" } | { kind: "StopMovedOn" } | { kind: "GitRunning" } | { kind: "MergeFinished" } | { kind: "NoOperation" } | { kind: "UnknownTab"; tab: TabId } | { kind: "ColumnTooLarge"; limit: number } | { kind: "UnknownRangeFile"; file: RangeFileId } | { kind: "WorkerStopped" } | { kind: "UnknownThread"; thread: ThreadId } | { kind: "UnknownMessage"; message: MessageId } | { kind: "EmptyMessage" } | { kind: "MessagePending"; message: MessageId } | { kind: "NotANote"; message: MessageId } | { kind: "SendRunning" } | { kind: "AiOff" } | { kind: "RemoveFailed"; folder: string; message: string };

/**  A failed job's log as the window shows it. */
export type JobLog = {
	/**  The log as GitLab stores it, colour codes and all; bytes that are not UTF-8 read as U+FFFD. */
	text: string,
	/**  Whether earlier lines were left out: the log was longer than `MAX_LOG_BYTES`. */
	cut: boolean,
};

/**  How asking for a failed job's log ended. */
export type JobLogReply = 
/**  GitLab's log of the job. */
{ kind: "log"; 
/**  The log. */
log: JobLog } | 
/**  This window's list never offered that job page (or the page is no job's), so nothing was asked. */
{ kind: "notOffered" } | 
/**  GitLab has no log for the job: an empty answer or HTTP 404. */
{ kind: "noLog" } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  glab failed, timed out or answered something unexpected, in glab's or yamt's words. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**
 *  `Some(keys)` replaces the action's entry (an empty list = the action has no key);
 *  `None` removes the entry (the action is back on its defaults).
 */
export type KeysChange = {
	action: string,
	keys: string[] | null,
};

/**  A label of a merge request; `colors` is `None` when either colour is missing or not `#rgb`/`#rrggbb`. */
export type Label = {
	/**  Its title. */
	title: string,
	/**  Its colours. */
	colors: LabelColors | null,
};

/**  A label's colours as GitLab sends them, each `#rgb` or `#rrggbb` (checked: `#` then 3 or 6 hex digits). */
export type LabelColors = {
	/**  The chip's colour. */
	background: string,
	/**  The colour of its title. */
	text: string,
};

/**
 *  `repositories`: the answer to "Start this project's language servers?" per repository root
 *  (the exact path text the window gets); `added`: the servers the user added by hand.
 */
export type LanguageServerSettings = {
	repositories: { [key in string]: RepositoryAnswer },
	/**  Repository root → the keys of the found servers switched off there (the window's text, opaque here). */
	off?: { [key in string]: string[] },
	added: AddedServer[],
};

/**  0-based line index in the left text of a 2-way compare. */
export type LeftLine = number;

/**  What a restore could not put back. */
export type Leftover = 
/**  HEAD moved after the merge started, so it stays where it is. */
{ kind: "notReturned"; to: ReturnTo } | { kind: "returnRefused"; to: ReturnTo; message: string } | 
/**  The branch moved after the merge started, so it stays where it is. */
{ kind: "branchKept"; branch: string } | 
/**  The branch the start created is still checked out (its return was refused or not done), so it stays. */
{ kind: "branchCheckedOut"; branch: string } | { kind: "branchRefused"; branch: string; message: string };

/**  Where two texts differ, by lines only: the same ranges as a [`Difference`], without its word marks. */
export type LineChange = {
	/**  The lines in the left; empty where the right inserted lines. */
	left: LineRange<LeftLine>,
	/**  The lines in the right; empty where the right removed the left's lines. */
	right: LineRange<RightLine>,
};

/**  The lines `start .. start + len` of one text; built from a length, so it cannot be inverted. */
export type LineRange<L> = {
	/**  First line of the range, or the insertion point when the range is empty. */
	start: L,
	/**  Number of lines in the range. */
	len: number,
};

/**  A commit or a commit range the description links to. */
export type LinkedCommit = {
	/**  `fa3335f3`, `web@fa3335f3`, `other/lib@fa3335f3`, `a1b2c3d4…e5f6a7b8`. */
	reference: string,
	/**  Its first mention's address, as the description resolved it. */
	page: WebPage,
	/**
	 *  GitLab's `title` on its reference link (a commit's first message line; a range's "Commits … through …");
	 *  None: GitLab made no reference of it for this user ("Not found or no access").
	 */
	title: string | null,
};

/**  An epic the description links to. */
export type LinkedEpic = {
	/**  As GitLab writes it from the merge request's project: `&3`, `group/sub&3`. */
	reference: string,
	/**  Its first mention's address, as the description resolved it. */
	page: WebPage,
	/**  None: GitLab did not show it to this user ("Not found or no access"). */
	shown: ShownEpic | null,
};

/**  An issue the description links to. */
export type LinkedIssue = {
	/**  As GitLab writes it from the merge request's project: `#12`, `web#12`, `other/lib#12`. */
	reference: string,
	/**  Its first mention's address, as the description resolved it. */
	page: WebPage,
	/**  None: GitLab did not show it to this user ("Not found or no access"). */
	shown: ShownIssue | null,
};

/**  An issue's direct parent. */
export type LinkedParent = {
	/**  As GitLab writes it from the merge request's project. */
	reference: string,
	/**  Its title. */
	title: string,
	/**  GitLab's address of it. */
	page: WebPage,
};

/**  How reading the epics, issues and commits a merge request's description links to ended. */
export type LinksReply = 
/**  The description's links, looked up. */
{ kind: "read"; 
/**  The links. */
links: DescriptionLinks } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  glab's or GitLab's words, `page.rs` `NO_MERGE_REQUEST` or `NO_PROJECT`. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  How a load ended; the pages already sent stay. */
export type ListEnd = 
/**  Every open merge request was sent. */
{ kind: "loaded" } | 
/**  The newest `limit` were sent; GitLab has more. */
{ kind: "cut"; 
/**  How many were sent. */
limit: number } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first output line, which names the instance. */
detail: string } | 
/**  glab failed, timed out or answered something unexpected. */
{ kind: "failed"; 
/**  What went wrong, in glab's, GitLab's or yamt's words. */
message: string };

/**
 *  One message of a load, in order: every page, then its end, then each row the local conflict check changed. The
 *  end travels on the channel too: tauri 2.12.1 delivers a channel message of 8 KiB of JSON or more by a later fetch
 *  (ipc/channel.rs `MAX_JSON_DIRECT_EXECUTE_THRESHOLD`), so a page could reach the window after the command's own
 *  answer.
 */
export type ListMessage = { kind: "page"; page: MergeRequestPage } | { kind: "end"; end: ListEnd } | { kind: "checked"; row: CheckedRow };

/**  How a list numbers its items. */
export type ListNumbering = 
/**  `<ul>`. */
{ kind: "bullets" } | 
/**  `<ol>`. */
{ kind: "numbers"; 
/**  The first item's number: `<ol start>`, else 1. */
start: number };

/**  The files of the stop as git sees them, or `MovedOn`: git is at another stop, the next list opens it. */
export type Listing = { kind: "Files"; files: FileEntry[]; disk_changes: DiskChange[]; operation: OperationView | null; sides: SideNames; 
/**  The merge yamt started at this stop, from its record; `None` for any other stop. */
merge_request: MergeView | null } | { kind: "MovedOn" };

/**  0-based line index in the local text. */
export type LocalLine = number;

/**  Whether a merge yamt started is unfinished in a repository. */
export type LocalMerge = { kind: "free" } | { kind: "merging"; iid: number; windowOpen: boolean };

export type LogEntry = {
	level: LogLevel,
	event: string,
	fields: { [key in string]: LogValue },
};

export type LogLevel = "debug" | "info" | "warn" | "error";

export type LogValue = string | number | null | boolean;

/**  What the merge requests were looked up by. */
export type LookedAt = 
/**  The right side's branch: its open merge requests. */
{ kind: "branch"; 
/**  The branch, without `refs/heads/` or a remote. */
name: string } | 
/**  The right commit, as the range names no branch: the open merge requests ending at it. */
{ kind: "commit"; 
/**  The commit's short id. */
short_id: string };

/**  How previewing a text as GitLab renders it ended. */
export type MarkdownPreviewReply = 
/**  GitLab's rendering of the text as yamt shows it; no blocks for a blank text. */
{ kind: "read"; 
/**  The rendering. */
preview: Description } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  glab's or GitLab's words, or `page.rs` `NO_PROJECT`. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  A user GitLab linked as a mention in a note: `a[data-reference-type="user"][data-user]` of its `bodyHtml`. */
export type Mention = {
	/**  The `href`'s last path segment, when it is `[A-Za-z0-9_.-]+` (else the link is not a mention). */
	username: string,
	/**  The link's `title` (GitLab's name of the user), else the username. */
	name: string,
};

export type MergeChunk = {
	chunk: Chunk,
	middle: LineRange<MiddleLine>,
	words: WordChanges,
	waiting: Waiting,
};

/**  A merge request's number within its project, "!12" without the "!". */
export type MergeRequestIid = number;

/**  One page of the list, sent as soon as it arrives. */
export type MergeRequestPage = {
	/**  The logged-in user's username. */
	me: string | null,
	/**  The page's merge requests, newest first. */
	rows: MergeRequestRow[],
};

/**  A merge request's assignees and reviewers as GitLab answered. */
export type MergeRequestPeople = {
	/**  Its assignees. */
	assignees: Person[],
	/**  Its reviewers and how far each review is. */
	reviewers: Reviewer[],
};

/**  A merge request as the window names it. */
export type MergeRequestRef = {
	/**  Its short reference, "!12". */
	reference: string,
	/**  Its title. */
	title: string,
	/**  Its page on GitLab. */
	web_url: string,
};

/**  One open merge request as a row of the list. */
export type MergeRequestRow = {
	/**  Its number. */
	iid: MergeRequestIid,
	/**  Its title, GitLab's "Draft: " prefix included. */
	title: string,
	/**  GitLab's description holds more than white space. */
	hasDescription: boolean,
	/**  GitLab's ISO 8601 time, as sent. */
	createdAt: string,
	/**  Whether it is a draft. */
	draft: boolean,
	/**  Who opened it; `None` when GitLab names no one. */
	author: Person | null,
	/**  Its assignees. */
	assignees: Person[],
	/**  Its reviewers and how far each review is. */
	reviewers: Reviewer[],
	/**  Its labels, in GitLab's order. */
	labels: Label[],
	/**  Resolvable discussions not yet resolved. */
	openDiscussions: number,
	/**  Who approved it. */
	approvedBy: Person[],
	/**
	 *  GitLab's `updateMergeRequest` permission for you: whether you may re-request a review and add or remove
	 *  assignees and reviewers.
	 */
	mayRerequest: boolean,
	/**  Its latest pipeline; `None` when it has none. */
	pipeline: Pipeline | null,
	/**  Its page on GitLab; `None` when GitLab is not on https. */
	page: WebPage | null,
	/**  How much it changes; `None` when GitLab has not computed its diff. */
	size: ChangeSize | null,
	/**  Whether it can be merged. */
	readiness: Readiness,
	/**  Whether its branch lives in another project than its target, or in a deleted one. */
	fromFork: boolean,
};

/**  The recorded merge as the merge window shows it. */
export type MergeView = {
	branch: string,
	target: string,
	/**  `None` when the branch itself was checked out before. */
	returnTo: ReturnTo | null,
	branchBefore: BranchBefore,
};

/**  One message of a thread. */
export type Message = {
	/**  The message's id. */
	id: MessageId,
	/**  What it says. */
	body: MessageBody,
	/**  When it was added, in seconds since 1970. */
	written: number,
	/**  Where it stands on its way to GitLab. */
	posting: Posting,
};

/**  What a message says. */
export type MessageBody = 
/**  Text the user wrote. */
{ kind: "note"; 
/**  The text as written. */
text: string } | 
/**  An AI answer, kept in the AI's own session. */
{ kind: "aiAnswer"; 
/**  The session the answer lives in. */
session: string; 
/**  The answer's turn among that session's answers in the thread, from 0. */
turn: number };

/**  A message's identity; ids never repeat within a pair folder. */
export type MessageId = number;

/**  Where the middle pane starts: yamt's merge of the stages (base), or the file as found on disk. */
export type Middle = { kind: "Stages"; text: string } | { kind: "Disk"; text: string } | { kind: "DiskNotText"; found: NotText };

/**  0-based line of the middle pane's starting text. */
export type MiddleLine = number;

/**  Why posting is disabled: GitLab's diff is not the window's, or GitLab could not be asked. */
export type NotLinedUp = 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first output line, which names the instance. */
detail: string } | 
/**  No open merge request was found. */
{ kind: "noMergeRequest"; 
/**  What was looked up. */
looked_at: LookedAt } | 
/**  Several open merge requests, none of them lining up. */
{ kind: "several"; 
/**  What was looked up. */
looked_at: LookedAt; 
/**  Their references, "!12". */
references: string[] } | 
/**  The merge request's diff ends at another commit. */
{ kind: "moved"; 
/**  The merge request. */
merge_request: MergeRequestRef; 
/**  The short id GitLab's diff ends at. */
gitlab_head: string; 
/**  The short id the window's right side is. */
shown_head: string } | 
/**  The merge request's diff starts from another commit. */
{ kind: "otherBase"; 
/**  The merge request. */
merge_request: MergeRequestRef; 
/**  The short id GitLab's diff starts from. */
gitlab_base: string; 
/**  The short id the window's left side is. */
shown_base: string } | 
/**  GitLab still prepares the merge request's diff. */
{ kind: "preparing"; 
/**  The merge request. */
merge_request: MergeRequestRef } | 
/**  glab failed, timed out or answered something unexpected. */
{ kind: "failed"; 
/**  What went wrong, in glab's or yamt's words. */
message: string };

/**  Why the file on disk cannot be shown as the middle text. */
export type NotText = "Deleted" | "Binary" | "NonUtf8" | "TooLarge" | "Link" | "Directory";

/**  When and by whom a comment was last edited. */
export type NoteEdit = {
	/**  GitLab's ISO 8601 time, as sent. */
	at: string,
	/**  Who edited it. */
	by: Person,
};

/**  A discussion and what the turn rule needs of it: every note written by a person (system notes skipped). */
export type OpenDiscussion = {
	/**  Its id. */
	id: DiscussionId,
	/**  Where it is: the first person note's `position` (GitLab's place of the discussion). */
	place: DiscussionPlace,
	/**  Every person note before `last`, oldest first: `earlier[0]` (or `last` when empty) started the discussion. */
	earlier: TurnComment[],
	/**  Its last person note. */
	last: DiscussionNote,
};

/**  How asking to open a merge request's changes ended. */
export type OpenReply = 
/**  A new window shows them. */
{ kind: "opened" } | 
/**  Another yamt window shows the same two commits. */
{ kind: "alreadyOpen" } | 
/**  GitLab still prepares the merge request's diff. */
{ kind: "preparing" } | 
/**  The merge request is no longer open. */
{ kind: "notOpen" } | 
/**  No remote of the repository names the project, so its commits cannot be fetched. */
{ kind: "noRemote"; 
/**  The project's full path, `group/project`. */
project: string } | 
/**  Fetching the merge request's commits failed. */
{ kind: "fetchFailed"; 
/**  git's first line: the cause. */
message: string } | 
/**  A commit of GitLab's diff is not in the repository, even after the fetch. */
{ kind: "missingCommit"; 
/**  Its short id. */
short_id: string } | 
/**  The new window's yamt did not start. */
{ kind: "startFailed"; 
/**  Why, in the system's words. */
message: string } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first output line, which names the instance. */
detail: string } | 
/**  glab or git failed, timed out or answered something unexpected. */
{ kind: "failed"; 
/**  What went wrong, in glab's, GitLab's, git's or yamt's words. */
message: string };

/**  What git is doing, with the names of what it applies (plan §2 #87). */
export type OperationView = { kind: "Merge"; merging: SideName | null; into: SideName | null } | { kind: "SquashMerge"; merging: SideName | null; into: SideName | null } | { kind: "Rebase"; branch: string | null; onto: SideName | null; replaying: SideName | null; progress: ProgressView | null; editor_steps_ahead: boolean } | { kind: "CherryPick"; picking: SideName | null; progress: ProgressView | null } | { kind: "Revert"; reverting: SideName | null; progress: ProgressView | null } | { kind: "Am"; subject: string; message: string; progress: ProgressView | null };

/**  How asking to open a page on GitLab ended. */
export type PageOpened = 
/**  The browser was asked to show it. */
{ kind: "opened" } | 
/**  This window's list never offered that address, so it is not opened. */
{ kind: "notOffered" } | 
/**  The browser could not be asked. */
{ kind: "failed"; 
/**  Why, in the system's words. */
message: string };

/**  A draft's raw text as written (GitLab's draft list sends no rendering; design §4 item 3). */
export type PendingDraft = {
	/**  The text. */
	text: string,
};

/**  Whether a change adds a person to a list or removes them from it. */
export type PeopleAction = 
/**  Add them to GitLab's list as it is then (`APPEND`). */
"add" | 
/**  Remove them from GitLab's list as it is then (`REMOVE`). */
"remove";

/**  One person added to or removed from one list of a merge request. */
export type PeopleChange = {
	/**  The list. */
	group: PeopleGroup,
	/**  Add or remove. */
	action: PeopleAction,
	/**  Who, by their login name without "@". */
	username: string,
};

/**  How asking GitLab for one change ended. */
export type PeopleChangeReply = 
/**  GitLab's answered list shows the change: both lists as answered. */
{ kind: "changed"; 
/**  Both lists as GitLab answered. */
people: MergeRequestPeople } | 
/**
 *  GitLab answered without an error but its list does not show the change (GitLab Free keeps one assignee and one
 *  reviewer; no permission; an unknown user): both lists as answered.
 */
{ kind: "unchanged"; 
/**  Both lists as GitLab answered. */
people: MergeRequestPeople } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  GitLab refused, in its words: the payload's first `errors` entry. */
{ kind: "refused"; 
/**  GitLab's sentence. */
message: string } | 
/**  glab failed, GitLab's top-level error, or an answer naming no merge request. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  Which list of a merge request a change is for. */
export type PeopleGroup = 
/**  Its assignees. */
"assignees" | 
/**  Its reviewers. */
"reviewers";

/**  How searching the project's people ended. */
export type PeopleSearchReply = 
/**  Who matched, in GitLab's order: at most 20 (GitLab's `Autocomplete::UsersFinder::LIMIT`). */
{ kind: "found"; 
/**  The people found. */
people: Person[] } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  glab's, GitLab's or yamt's words (an older GitLab's "Field 'autocompleteUsers' doesn't exist…" included). */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  A GitLab user and the picture the window may show for them. */
export type Person = {
	/**  The login name, without "@". */
	username: string,
	/**  The display name. */
	name: string,
	/**  The picture the window shows for them. */
	picture: PersonPicture,
};

/**  Which picture the window shows for a person. */
export type PersonPicture = 
/**  Uploaded to the project's GitLab: the window asks `yamt-picture://localhost/<username>`. */
{ kind: "uploaded" } | 
/**  A Gravatar picture: the window loads this address itself. */
{ kind: "gravatar"; 
/**  The picture's address on Gravatar. */
address: GravatarAddress } | 
/**  Nothing yamt may load: initials. */
{ kind: "none" };

/**  A merge request's latest pipeline. */
export type Pipeline = {
	/**  Its status. */
	status: CiStatus,
	/**  Its failed jobs, in GitLab's order. */
	failedJobs: FailedJob[],
	/**  Whether it has more failed jobs than were asked for. */
	moreFailedJobs: boolean,
};

/**  Where a message stands on its way to GitLab. */
export type Posting = 
/**  Not meant for GitLab. */
{ kind: "notQueued" } | 
/**  Waiting for the next send. */
{ kind: "queued"; 
/**  The text to post, as edited. */
text: string } | 
/**  GitLab refused it; it is sent again with the next send. */
{ kind: "refused"; 
/**  The text to post, as edited. */
text: string; 
/**  GitLab's words. */
reason: string } | 
/**  Posted as a draft note of the user's pending review. */
{ kind: "pending"; 
/**  The text posted. */
text: string; 
/**  GitLab's id of the draft note. */
draft_note: number; 
/**  The merge request's reference, "!12". */
merge_request: string; 
/**  The merge request's Changes page. */
link: string };

/**
 *  Folders a server's program is looked for in besides PATH (plan §2 #72). Each entry is a relative path of plain
 *  names separated by `/` (`node_modules/.bin`, `.venv/Scripts`, `go/bin`); an entry that is empty, absolute,
 *  holds `..` or `.`, or has an empty name (`go/bin/`, `a//b`) is skipped.
 */
export type ProgramFolders = {
	/**  Tried in the project folder, then each parent up to the repository root; within one folder in list order. */
	project: string[],
	/**  Tried after every PATH entry, relative to the user's home folder. */
	home: string[],
};

export type ProgramFound = { kind: "Found"; path: string; place: ProgramPlace } | { kind: "NotFound"; searched: string[] };

export type ProgramPlace = "Project" | "Path" | "Home";

/**  Step `step` of `total`, 1 ≤ step ≤ total. */
export type ProgressView = {
	step: number,
	total: number,
};

/**  What a repository-relative path holds, for detection; a path outside the repository is `Missing`. */
export type ProjectFile = { kind: "Missing" } | { kind: "Folder" } | { kind: "Text"; text: string } | { kind: "TooLarge" } | { kind: "NotText" };

export type PushReply = { kind: "pushed" } | 
/**  git's words: the ref's rejection, else its first `fatal:`/`error:` line. */
{ kind: "failed"; message: string };

export type RangeChange = { kind: "added" } | { kind: "modified" } | { kind: "deleted" } | { kind: "renamed"; old_path: string };

/**  One row of the list; `path` is the new path, the old one for a deleted file (UTF-8, lossy for display). */
export type RangeEntry = {
	id: RangeFileId,
	path: string,
	change: RangeChange,
	lines: RangeLineCounts,
};

export type RangeEntryKind = "file" | "executable" | "link" | "submodule";

/**  What one file shows: decided once, here. */
export type RangeFile = { kind: "texts"; left: string; right: string; differences: Difference[]; mode: RangeModeChange } | { kind: "binary" } | { kind: "tooLarge"; limit: number } | { kind: "notUtf8"; sides: RangeSides } | { kind: "modeOnly"; old: RangeEntryKind; new: RangeEntryKind } | { kind: "kindChanged"; old: RangeEntryKind; new: RangeEntryKind } | { kind: "submodule"; old: string | null; new: string | null };

/**  A changed file's place in the range's list: 0.. in list order, fixed for the window's life. */
export type RangeFileId = number;

export type RangeLineCounts = { kind: "counted"; added: number; removed: number } | { kind: "notCounted" };

export type RangeModeChange = { kind: "same" } | { kind: "changed"; old: RangeEntryKind; new: RangeEntryKind };

export type RangeSide = {
	label: RangeSideLabel,
	short_id: string,
	subject: string,
};

/**  How a column header names its side. */
export type RangeSideLabel = 
/**  A side as typed; an empty side is `HEAD`. */
{ kind: "named"; name: string } | 
/**  The left of `a...b`: where `right` branched off `left`. */
{ kind: "mergeBase"; left: string; right: string };

export type RangeSides = "left" | "right" | "both";

export type RangeStart = {
	range: string,
	left: RangeSide,
	right: RangeSide,
	files: RangeEntry[],
};

/**
 *  Whether a merge request can be merged, GitLab's `detailedMergeStatus` folded with its `conflicts` flag, or with
 *  yamt's own merge of its two commits: one state per row, a conflict first.
 */
export type Readiness = 
/**  It can be merged. */
{ kind: "ready" } | 
/**  Its branch conflicts with its target. */
{ kind: "conflicts"; 
/**  What else blocks it, GitLab's status first, then `Draft`; empty when nothing else is known. */
also: BlockedReason[] } | 
/**  Its branch must be rebased first. */
{ kind: "needsRebase" } | 
/**  GitLab still checks whether it can be merged. */
{ kind: "checking" } | 
/**  Something other than a conflict blocks it. */
{ kind: "blocked"; 
/**  What blocks it. */
reason: BlockedReason } | 
/**
 *  yamt's own merge of GitLab's two commits is clean, and GitLab's status says nothing of the other blockers:
 *  it still checks, or keeps a conflict that hides them (request rule 3).
 */
{ kind: "mergesCleanly" };

/**  Why a start changed nothing (or, for `GitRefused` with leftovers, could not put everything back). */
export type Refusal = 
/**  `Some`: the iid of the unfinished merge; `None`: another start holds the start lock. */
{ kind: "alreadyMerging"; iid: number | null } | 
/**  git is in the middle of another operation. */
{ kind: "busy" } | { kind: "uncommittedChanges" } | { kind: "fetchFailed"; message: string } | 
/**  The local branch has commits GitLab's does not. */
{ kind: "localAhead"; branch: string } | { kind: "alreadyContains"; branch: string; target: string } | { kind: "gitRefused"; message: string; left: Leftover[] } | { kind: "recordUnreadable"; path: string; message: string };

/**  0-based line index in the remote text. */
export type RemoteLine = number;

/**
 *  Text the compared-with text has that this side lacks, and the place in this side where it
 *  would sit.
 */
export type Removal<L> = {
	/**  The zero-width place in this side where the missing text would sit. */
	at: InlinePoint<L>,
	/**  The missing text, every line break written `\n`; never empty. */
	text: string,
};

/**  How a reply is posted: at once, or as a draft of the viewer's review. */
export type ReplyKind = 
/**  A comment everyone sees now. */
"comment" | 
/**  A draft, published with the review. */
"draft";

export type RepositoryAnswer = "start" | "dontStart";

/**  How asking GitLab to re-request a reviewer's review ended. */
export type RerequestReply = 
/**  Done, or already awaiting their review; the merge request's reviewers as GitLab answered. */
{ kind: "requested"; 
/**  The merge request's reviewers now. */
reviewers: Reviewer[] } | 
/**  They are no longer a reviewer of the merge request: nothing was written (owner #2100, #2104). */
{ kind: "notReviewer" } | 
/**  The merge request is no longer open. */
{ kind: "notOpen" } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first line, which names the instance. */
detail: string } | 
/**  GitLab refused, in its words (the mutation's first `errors` entry). */
{ kind: "refused"; 
/**  GitLab's sentence. */
message: string } | 
/**  glab failed, timed out or answered something unexpected, in glab's, GitLab's or yamt's words. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**  Why the branches of a merge request to resolve are not given. */
export type ResolveRefusal = 
/**  The merge request is no longer open. */
{ kind: "notOpen" } | 
/**  Its source branch lives in another project. */
{ kind: "fromFork" } | 
/**  No remote of the repository names the project. */
{ kind: "noRemote"; 
/**  The project's full path, `group/project`. */
project: string } | 
/**  glab is not found on PATH. */
{ kind: "glabMissing" } | 
/**  `glab auth status` failed. */
{ kind: "notLoggedIn"; 
/**  glab's first output line, which names the instance. */
detail: string } | 
/**  glab failed, timed out or answered something unexpected. */
{ kind: "failed"; 
/**  What went wrong, in glab's, GitLab's or yamt's words. */
message: string };

/**
 *  What resolving a merge request's conflicts did (plan §2 #139): a merge started in this checkout and its
 *  window started or not, or why nothing changed.
 */
export type ResolveReply = { kind: "started"; started: Started } | { kind: "windowFailed"; started: Started; message: string } | { kind: "refused"; refusal: Refusal } | { kind: "gitLabRefused"; refusal: ResolveRefusal };

/**  Where Abort returns HEAD to. */
export type ReturnTo = { kind: "branch"; name: string } | 
/**  `id`: the commit's first 7 hex characters. */
{ kind: "commit"; id: string };

/**  How far a reviewer's review is: GitLab's state in the four the window names. */
export type ReviewState = 
/**  Their review is asked for, or under way. */
"requested" | 
/**  They reviewed without approving. */
"reviewed" | 
/**  They approved. */
"approved" | 
/**  They asked for changes. */
"changesRequested";

/**  A reviewer of a merge request and how far their review is. */
export type Reviewer = {
	/**  Who reviews. */
	person: Person,
	/**  How far their review is. */
	state: ReviewState,
};

/**  0-based line index in the right text of a 2-way compare. */
export type RightLine = number;

/**  One merge request's open discussions, or why they were not read. */
export type RowDiscussions = {
	/**  The merge request. */
	iid: MergeRequestIid,
	/**  Its open discussions, or why there are none to show. */
	answer: DiscussionsAnswer,
};

export type RunId = number;

/**  One text file's two sides as `RangeFile::Texts` holds them, with the lines that differ. */
export type SearchText = {
	file: RangeFileId,
	left: string,
	right: string,
	changes: LineChange[],
};

/**  One page of the range's text files; `next` is the id the following page starts at, `None` after the last file. */
export type SearchTexts = {
	files: SearchText[],
	next: RangeFileId | null,
};

/**  How far a send is: `done` of `of` messages. */
export type SendProgress = {
	/**  The messages handled so far. */
	done: number,
	/**  The messages the send handles. */
	of: number,
};

/**  How a send ended. */
export type SendReply = 
/**  GitLab's diff is not the window's; nothing was sent. */
{ kind: "notLinedUp"; 
/**  Why. */
why: NotLinedUp } | 
/**  Every queued message was handled. */
{ kind: "sent"; 
/**  The threads after the send. */
list: ThreadList; 
/**  Messages now pending on GitLab. */
sent: number; 
/**  Messages GitLab refused, still queued. */
refused: number } | 
/**  The send stopped; the message it stopped at and the rest stay queued. */
{ kind: "stopped"; 
/**  The threads after the send. */
list: ThreadList; 
/**  Messages now pending on GitLab. */
sent: number; 
/**  Messages GitLab refused, still queued. */
refused: number; 
/**  Why it stopped. */
reason: string };

/**  `project`: the repository-relative folder the program runs in (`""` = the root, `/` separators). */
export type ServerCommand = {
	program: string,
	args: string[],
	project: string,
	folders: ProgramFolders,
};

/**  `root`: the repository's folder, `None` when its path is not UTF-8. */
export type ServerContext = {
	root: string | null,
	process_id: number,
};

export type SettingsRead = {
	path: string,
	default_path: string,
	stored: StoredSettings,
};

/**  What GitLab shows of an epic. */
export type ShownEpic = {
	/**  Its title. */
	title: string,
	/**  Whether it is closed. */
	closed: boolean,
};

/**
 *  What GitLab shows of an issue. `parent`: the direct parent (an epic, or the issue above a task) when GitLab names
 *  one on the project's server.
 */
export type ShownIssue = {
	/**  Its title. */
	title: string,
	/**  Whether it is closed. */
	closed: boolean,
	/**  Its direct parent. */
	parent: LinkedParent | null,
};

export type Side = "local" | "remote";

export type SideContent = { kind: "Missing" } | { kind: "Text"; lines: number } | { kind: "Binary"; bytes: number } | { kind: "NonUtf8"; bytes: number } | { kind: "TooLarge"; bytes: number } | { kind: "Link"; target: string } | { kind: "Commit"; id: string };

/**
 *  What one side of the operation is: a branch, a commit, the commit a revert undoes, or the
 *  patch `git am` applies.
 */
export type SideName = { kind: "Branch"; name: string } | { kind: "Commit"; short_id: string; subject: string; message: string } | { kind: "Revert"; short_id: string; subject: string; message: string } | { kind: "Patch"; subject: string; message: string };

/**  Both panes' names, read once when the session opens; `None` when nothing names that side. */
export type SideNames = {
	local: SideName | null,
	remote: SideName | null,
};

/**  One side compared with another text, line by line. */
export type SideWordChanges<L> = {
	/**
	 *  Side text that is not in the compared-with text: sorted by line then start, disjoint,
	 *  never empty, never across a line break.
	 */
	changed: InlineRange<L>[],
	/**
	 *  Compared-with text this side lacks with nothing new in its place: sorted by place, at
	 *  most one per place.
	 */
	removals: Removal<L>[],
};

export type StartReply = { kind: "Started"; run: RunId } | { kind: "NotFound"; program: string; searched: string[] } | { kind: "SpawnFailed"; program: string; message: string } | { kind: "OutsideRepository"; project: string };

/**  A started merge: `target` merged into `branch`, stopped before its commit. */
export type Started = {
	branch: string,
	target: string,
	/**  false: GitLab's "has conflicts" was stale, the merge is clean. */
	conflicts: boolean,
};

/**
 *  What the window holds and sends: `keys` = action id → key strings, only for actions whose
 *  keys differ from the defaults (the window knows the defaults; Rust never does).
 */
export type StoredSettings = {
	theme: Theme,
	antialiasing: Antialiasing,
	keys: { [key in string]: string[] },
	languageServers: LanguageServerSettings,
	agent: AgentSettings,
	discussionDetails: DiscussionDetails,
};

/**  One tab as the window lists it. */
export type TabEntry = {
	/**  The tab's id. */
	id: TabId,
	/**  The tab's name. */
	name: string,
	/**  The tab's language. */
	language: TabLanguage,
	/**  Either column holds text. */
	holds_text: boolean,
};

/**  A tab's identity; ids never repeat within a data folder. */
export type TabId = number;

/**  The language a tab shows both columns in. */
export type TabLanguage = 
/**  Detected by the window from the texts. */
{ kind: "auto" } | 
/**  Picked by the user. */
{ kind: "picked"; 
/**  A window language name, opaque here. */
name: string };

/**  Every tab in the stored order, and the one shown. */
export type TabList = {
	/**  The tabs in the stored order. */
	tabs: TabEntry[],
	/**  The shown tab, always one of `tabs`. */
	shown: TabId,
};

/**  A tab's two texts and their comparison. */
export type TabTexts = {
	/**  The left text. */
	left: string,
	/**  The right text. */
	right: string,
	/**  The comparison of the two. */
	comparison: Comparison,
};

/**
 *  GitLab's task box: `input.task-list-item-checkbox` first in the item; `data-inapplicable` → Inapplicable,
 *  `checked` → Done, else Open; no such input → None.
 */
export type TaskBox = 
/**  No task box: a plain item. */
"none" | 
/**  A task not done. */
"open" | 
/**  A task done. */
"done" | 
/**  A task GitLab marks not applicable. */
"inapplicable";

export type Theme = "dark" | "light" | "webstorm-dark" | "webstorm-light" | "vscode-dark" | "vscode-light" | "zed-dark" | "zed-light" | "atom-dark" | "atom-light";

/**  A thread on lines of one file of the range. */
export type Thread = {
	/**  The thread's id. */
	id: ThreadId,
	/**  The file it is on. */
	file: RangeFileId,
	/**  The lines it is on. */
	place: ThreadPlace,
	/**  Its messages in the order they were added; never empty. */
	messages: Message[],
	/**  The AI session the thread's answers live in. */
	session: string | null,
};

/**  A new thread's id, and the threads with it. */
export type ThreadAdded = {
	/**  The new thread. */
	thread: ThreadId,
	/**  Every thread, the new one last. */
	list: ThreadList,
};

/**  A thread's identity; ids never repeat within a pair folder. */
export type ThreadId = number;

/**  The line a thread is on; the variant decides the column that shows it. */
export type ThreadLine = 
/**  A left line inside a difference. */
{ kind: "removed"; 
/**  The line. */
left: LeftLine } | 
/**  A right line inside a difference. */
{ kind: "added"; 
/**  The line. */
right: RightLine } | 
/**  An unchanged line, shown in the left column. */
{ kind: "unchangedOnLeft"; 
/**  The line in the left text. */
left: LeftLine; 
/**  The same line in the right text. */
right: RightLine } | 
/**  An unchanged line, shown in the right column. */
{ kind: "unchangedOnRight"; 
/**  The line in the left text. */
left: LeftLine; 
/**  The same line in the right text. */
right: RightLine };

/**  Every thread on a file of the range, in the order they were made. */
export type ThreadList = {
	/**  The threads. */
	threads: Thread[],
};

/**
 *  The lines a thread is on, from `start` to `end` in GitLab's order, both included; one line when `start` is `end`'s
 *  line. `end` decides the column the box sits in.
 */
export type ThreadPlace = {
	/**  The first line. */
	start: DiffLine,
	/**  The last line, in the column it was picked in. */
	end: ThreadLine,
};

/**  A person note before the last, as the turn rule reads it. */
export type TurnComment = {
	/**  Who wrote it; `None` for a deleted user. */
	author: Person | null,
	/**  The users it mentions. */
	mentions: Mention[],
};

export type UnsupportedReason = "Binary" | "NonUtf8" | "TooLarge" | "LocalDeleted" | "RemoteDeleted" | "Symlink" | "Submodule";

/**
 *  `upload~<the upload's 32 hex digit secret>`; `~` is in no username, so it never names an avatar. Only
 *  `description/address.rs` makes one.
 */
export type UploadKey = string;

/**  What Save writes for this change while a side of it still waits (plan §2 #69). */
export type Waiting = 
/**  One side changed these lines, or both the same way: written applied, as git wrote it. */
{ kind: "SideLines" } | 
/**
 *  A conflict as git writes it: `open`, the section of the pane `first` (git's ours: HEAD),
 *  `between` (base section if any, then the separator), the other pane's section, `close`.
 *  Lines without line breaks.
 */
{ kind: "Markers"; open: string; first: Side; between: string[]; close: string } | 
/**  A region yamt could not place: written as the Result shows it. */
{ kind: "AsShown" } | 
/**
 *  A conflict git rerere resolved from a resolution recorded before: written as the Result
 *  shows it, rerere's text unless the user changed it (plan §2 #90).
 */
{ kind: "Remembered" };

/**
 *  The address of a page this window may open in the browser: a failed job's log, a merge request or a note on one,
 *  on the project's GitLab, or a link in a description; only `WebPage::job`, `::merge_request`, `::note` and
 *  `::linked` make one.
 */
export type WebPage = string;

/**  Where one chunk's sides differ from base. */
export type WordChanges = {
	/**  The chunk these changes belong to. */
	chunk: ChunkId,
	/**  Local compared with base. */
	local: SideWordChanges<LocalLine>,
	/**  Remote compared with base. */
	remote: SideWordChanges<RemoteLine>,
};

/**  What a write did: written, or nothing written because the file changed on disk first. */
export type WriteReply = { kind: "Written"; files: FileEntry[] } | { kind: "ChangedOnDisk"; files: FileEntry[]; change: DiskChange };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

